  "Evidence quality key — Strong evidence (Official data / Platform data) · Moderate evidence (Industry reports / Surveys / Modeled) ·": "证据质量图例 — 强证据（官方数据 / 平台数据）· 中等证据（行业报告 / 调研 / 模型测算）·",
  "Built from data and assumptions ·": "由数据与假设构建 ·",
  "Directional, for planning use. Notes: all numbers are illustrative; marked as Modeled or Estimated; sources include public data, industry reports, platform data (partnered), surveys, and internal analysis. All numbers are illustrative and for internal planning only.": "方向性参考，供规划使用。注：所有数字均为示意；标注为模型测算或估算；来源包括公开数据、行业报告、平台数据（合作）、调研与内部分析。所有数字仅为示意，仅供内部规划。",
  // ---- 11 Key Research Findings ----
  "Key Research Findings": "关键研究发现",
  "Six insights that shape the Next Card strategy. Notes on data: all figures are illustrative and used for directional insight only; Modeled or Estimated where indicated. Deck contents as printed: 01 Overview · 02 Opportunity · 03 User Insight · 04 Proposition · 05 Experience · 06 Model · 07 Impact ·": "塑造 Next Card 战略的六项洞察。数据说明：所有数字均为示意，仅用于方向性洞察；标注处为模型测算或估算。演示目录如原文：01 概览 · 02 机会 · 03 用户洞察 · 04 主张 · 05 体验 · 06 模型 · 07 影响 ·",
  "11 Key Research Findings": "11 关键研究发现",
  "· 12 Next Steps. Each card carries its own Evidence and Implication, as printed — select a card to highlight it:": "· 12 下一步。每张卡片都带有自己的证据与含义，如原文 — 选择一张卡片高亮：",
  "Gen Z density is insufficient without credit eligibility.": "只有 Z 世代密度、没有信贷资格是不够的。",
  "In campuses with high Gen Z density, modeled eligible-applicant rate is the strongest predictor of approved applications. (Modeled)": "在 Z 世代密度高的校园，模型测算的合格申请人比例是获批申请的最强预测指标。（模型测算）",
  "Prioritize eligibility modeling and pre-qualification to focus acquisition on convertible demand.": "优先做资格建模与预审，把获客聚焦于可转化的需求。",
  "High mobile-payment adoption reduces application friction.": "高移动支付普及度降低申请摩擦。",
  "Users in high mobile-payment-penetration areas show higher digital application completion rates. (Estimated)": "移动支付渗透率高地区的用户，数字申请完成率更高。（估算）",
  "Lead with fully digital journeys and one-tap verification to convert intent into approved applications.": "以全数字化旅程与一键验证打头，把意向转化为获批申请。",
  "Merchant density influences activation and repeat usage.": "商户密度影响激活与重复使用。",
  "Activation and 30-day repeat usage are higher in areas with greater next-gen merchant density. (Estimated)": "新世代商户密度更高的地区，激活率与 30 天重复使用率更高。（估算）",
  "Expand partnerships in youth-concentrated commercial zones and digital-first merchants.": "在青年集中的商业区与数字优先商户扩展合作。",
  "University and young-professional clusters enable efficient offline acquisition.": "高校与年轻职场人聚集区让线下获客更高效。",
  "Campus and nearby business districts deliver lower cost-per-approval and higher first-activation rates. (Estimated)": "校园及周边商务区带来更低的单次获批成本与更高的首次激活率。（估算）",
  "Deploy targeted campus programs and employer partnerships to scale high-quality pipeline.": "部署定向校园计划与雇主合作，规模化高质量线索池。",
  "High-frequency daily categories are more useful than occasional luxury rewards.": "高频日常类别比偶尔的奢侈奖励更有用。",
  "Spend concentration is highest in daily categories; users value practical savings over aspirational rewards. (Estimated)": "消费集中度在日常类别最高；用户更看重实际节省而非憧憬型奖励。（估算）",
  "Design rewards and offers around daily life — food, beverage, transport, and study.": "围绕日常生活设计奖励与优惠 — 餐饮、饮品、交通与学习。",
  "Responsible credit-building can differentiate the card beyond discounts.": "负责任的信用建设能让这张卡超越折扣形成差异。",
  "Users show strong interest in credit tracking, limit growth, and repayment tools. (Estimated)": "用户对信用追踪、额度成长与还款工具兴趣浓厚。（估算）",
  "Build trust with transparent credit-building tools that support long-term financial health.": "以透明的信用建设工具建立信任，支持长期财务健康。",
  "IMPLICATION": "含义",
  "Source: Internal analysis, third-party industry data, user research · Note: All numbers are illustrative. Modeled or Estimated.": "来源：内部分析、第三方行业数据、用户研究 · 注：所有数字均为示意。模型测算或估算。",
