  "Jobs, Pains and Desired Outcomes": "任务、痛点与期望结果",
  "A credit card concept for China Gen Z. All panels at rest around the printed centre quote — select a panel to highlight it:": "面向中国 Z 世代的信用卡概念。所有面板围绕原图中央引言排布 — 选择一个面板高亮：",
  "Context": "背景",
  "I am a Gen Z in China, starting to manage money on my own.": "我是中国的 Z 世代，刚开始自己管钱。",
  "I have limited credit history and want a simple way to get started.": "我的信用记录有限，想要一个简单的方式起步。",
  "I live mobile-first and expect seamless digital experiences in my daily life.": "我以手机为先，期望日常生活中无缝的数字体验。",
  "I want to build good money habits for my future.": "我想为未来养成良好的金钱习惯。",
  "Functional jobs": "功能性任务",
  "Easy and fair application with clear requirements.": "申请简单公平，要求清晰。",
  "Pay for everyday needs online and offline.": "线上线下支付日常所需。",
  "Track spending and manage budget in real time.": "实时追踪消费并管理预算。",
  "Set reminders and repay on time effortlessly.": "设置提醒，轻松按时还款。",
  "Stay in control with transparent limits and fees.": "以透明的限额与费用保持掌控。",
  "Emotional jobs": "情感性任务",
  "Feel confident that I can handle credit responsibly.": "相信自己能负责任地用好信用。",
  "Feel reassured with clear, friendly guidance.": "在清晰友好的引导下感到安心。",
  "Feel a sense of progress as I build my credit.": "在建立信用的过程中感受到进步。",
  "Feel safe that I won't be penalized for small mistakes.": "确信小失误不会被惩罚，感到安全。",
  "Social jobs": "社交性任务",
  "Be seen as responsible and independent by family and peers.": "在家人与同伴眼中是负责任、独立的人。",
  "Enjoy exclusive offers that fit my lifestyle.": "享受贴合我生活方式的专属优惠。",
  "Share achievements and benefits that reflect my choices.": "分享体现我选择的成就与权益。",
  "Pains": "痛点",
  "Hard to get approved with little credit history.": "信用记录少，很难获批。",
  "Process feels complicated and time-consuming.": "流程感觉复杂又耗时。",
  "Terms and fees are unclear or hard to understand.": "条款与费用不清晰、难理解。",
  "Worried about overspending and late fees.": "担心超支与滞纳金。",
  "Credit feels intimidating and out of reach.": "信用让人望而生畏、遥不可及。",
