  "Feel confident and in control of my money.": "对自己的钱感到自信且掌控。",
  "Look forward to more opportunities in the future.": "期待未来更多机会。",
  "“When I begin managing money independently, I want a card that is easy to obtain, useful in my daily life and helps me build financial confidence without making credit feel intimidating.”": "“当我开始独立管钱时，我想要一张容易获得、在日常生活中实用、能帮我建立财务自信、又不会让信用显得吓人的卡。”",
