  "RESPONSIBLE. TRANSPARENT. DESIGNED FOR ADULTS.": "负责任。透明。为成年人设计。",
  "Next Card uses a clear and responsible process to help adults apply with confidence, understand decisions, and manage their account wisely. Principles as printed:": "Next Card 用清晰、负责任的流程，帮助成年人自信地申请、看懂审批结果、明智地管理账户。原则如原文：",
  "18+ Adult First": "18+ 成年人优先",
  "— only applicants 18+ can apply ·": "— 只有 18 岁以上申请人可申请 ·",
  "Privacy by Design": "隐私内置于设计",
  "— minimal data, encrypted, you're in control ·": "— 最少数据、加密、由你掌控 ·",
  "Fair and Transparent": "公平透明",
  "— we evaluate ability to repay, not just credit history ·": "— 我们评估还款能力，而不只是信用记录 ·",
