  "You're in Control": "由你掌控",
  "— set controls, get reminders, avoid surprises. Push notification as printed: “NEXT CARD · now — Reminder: Your payment of ¥1,200.00 is due on May 28. Avoid late fees by paying on time.”": "— 设置管控、接收提醒、避免意外。推送通知如原文：“NEXT CARD · 现在 — 提醒：你的 ¥1,200.00 还款将于 5 月 28 日到期。按时还款可避免滞纳金。”",
  "Age Eligibility": "年龄资格",
  "Are you 18 years or older?": "你是否已年满 18 岁？",
  "Next Card is available for adults only. Note on the printed phone: “You must be at least 18 years old to apply.” Buttons: [Yes, I'm 18 or older] [No, I'm not 18 yet]": "Next Card 仅向成年人提供。原图手机上的说明：“申请者必须年满 18 岁。”按钮：[是的，我已满 18 岁] [不，我还未满 18 岁]",
  "Identity Verification": "身份验证",
  "Verify your identity": "验证你的身份",
  "We use bank-level security to protect your information. ID Card — scan the front and back of your ID · Face Verification — take a quick selfie for liveness check · Personal Information — confirm your name, date of birth, and contact details. “Your data is encrypted and used only for verification.” [Continue]": "我们采用银行级安全保护你的信息。身份证 — 扫描身份证正反面 · 人脸验证 — 快速自拍做活体检测 · 个人信息 — 确认姓名、出生日期与联系方式。“你的数据经加密，仅用于验证。”[继续]",
  "Status Information": "状态信息",
  "Tell us about your current status": "告诉我们你目前的状态",
  "This helps us understand your ability to manage credit. Options: I'm employed — Full-time or part-time (selected) · I'm a student — Full-time student · I'm self-employed — Business owner or freelancer · Other — Not listed above. [Continue]": "这有助于我们了解你管理信用的能力。选项：我已就业 — 全职或兼职（已选）· 我是学生 — 全日制学生 · 我是个体经营者 — 企业主或自由职业者 · 其他 — 以上都不是。[继续]",
  "Review and Decision": "审核与决定",
