  "Product Ecosystem Map": "产品生态图谱",
  "NEXT CARD — Credit Card for Gen Z in China. An integrated digital ecosystem that connects acquisition, product, engagement and data to deliver a seamless card experience for Gen Z. Legend as printed: → User Flow · ⇢ Data / Event Flow · ⇢ External Connection. Principles: Mobile First · Simple and Transparent · Rewarding and Personal · Trusted and Secure. The full four-column diagram, as printed — select a module to highlight it:": "NEXT CARD — 面向中国 Z 世代的信用卡。一个集成的数字生态，连接获客、产品、互动与数据，为 Z 世代交付无缝的卡体验。图例如原文：→ 用户流 · ⇢ 数据 / 事件流 · ⇢ 外部连接。原则：移动优先 · 简单透明 · 有回报且个性化 · 可信与安全。完整的四列图如原文 — 选择一个模块高亮：",
