  "Phone as printed: “Next is yours — A credit card designed for how Gen Z lives.” [Apply Now]": "手机如原文：“Next is yours — 为 Z 世代的生活方式设计的信用卡。”[立即申请]",
  "WeChat Mini Program": "微信小程序",
