  "Application intake, verification, decisioning and account setup: Application Intake · Identity Verification · Risk & Policy Decision · Account Setup.": "申请受理、验证、决策与账户设置：申请受理 · 身份验证 · 风险与政策决策 · 账户设置。",
  "Virtual Card": "虚拟卡",
  "Instantly issued virtual card for online and in-app payments. Card as printed: 6259 1088 8888 8888 · CVV 888 · VALID THRU 08/28.": "即时发放的虚拟卡，用于线上与应用内支付。卡面如原文：6259 1088 8888 8888 · CVV 888 · 有效期至 08/28。",
  "Mobile Card Dashboard": "移动卡仪表盘",
  "Manage card, track spend, repay and control in one place. Phone as printed: Total Balance ¥3,258.00 · Available Credit ¥26,742.00 · Pay / Repay / Installment / More · Recent Transactions: RUI Coffee −¥38.00.": "在一处管理卡片、追踪消费、还款与管控。手机如原文：总余额 ¥3,258.00 · 可用额度 ¥26,742.00 · 支付 / 还款 / 分期 / 更多 · 近期交易：RUI Coffee −¥38.00。",
