  "Eligibility check CVR 61.37%": "资格核查转化率 61.37%",
  "Tell us about you — Step 1 of 4. Employment [Select] · Monthly income [Select range] · Education [Select] · Residential address [Enter address]. [Next]": "先了解一下你 — 第 1 / 4 步。就业状况 [选择] · 月收入 [选择区间] · 学历 [选择] · 居住地址 [输入地址]。[下一步]",
