  "Verify your identity — Step 2 of 4. ID card: take a photo of your ID card · Face verification: take a selfie to verify. “We ensure your information is safe and secure.”": "验证你的身份 — 第 2 / 4 步。身份证：拍一张身份证照片 · 人脸验证：自拍验证。“我们确保你的信息安全无虞。”",
