  "GROWTH ENGINE": "增长引擎",
  "— Product experience drives growth. Growth unlocks better product. All seven stage columns plus the Outcome rail, as printed — select a stage to highlight it:": "— 产品体验驱动增长。增长解锁更好的产品。七个阶段列加上结果栏如原文 — 选择一个阶段高亮：",
