  "Notes: All metrics are modeled for illustration purposes based on internal benchmarks and market research. Actual results may vary based on execution and market conditions. Model Date: May 2024 | Market: China | Target Audience: Gen Z (18–26).": "注：所有指标均为基于内部基准与市场研究的示意性模型测算。实际结果可能因执行与市场条件而异。模型日期：2024 年 5 月 | 市场：中国 | 目标受众：Z 世代（18–26 岁）。",
