  "If not approved, transparently explain reason and offer credit builder path to requalify. (Not Approved — We're unable to approve your application now. [Learn More] · Reapply Later)": "如果未获批，透明地说明原因并提供信用建设路径以重新获得资格。（未获批 — 我们现在无法批准你的申请。[了解更多] · 稍后重新申请）",
  "First-time user?": "首次用户？",
