  "START → Landing → Benefits → Application → Approval → Dashboard → Rewards → Perks → Referral → Builder. ◆ = decision point. Tap a phone to select its stage.": "开始 → 落地页 → 权益 → 申请 → 审批 → 仪表盘 → 奖励 → 优惠 → 推荐 → 信用建设。◆ = 决策点。点击一部手机选择其阶段。",
  "Clarity first · Mobile-first layout · One primary action per screen · Consistent components · Accessible by default.": "清晰优先 · 移动优先布局 · 每屏一个主要操作 · 组件一致 · 默认无障碍。",
  "Activation Rate 28.4% · Application Completion 61.2% · Approval Rate 72.0% · 90-Day Retention 46.8% · Monthly Active Rate 38.7%.": "激活率 28.4% · 申请完成率 61.2% · 审批通过率 72.0% · 90 天留存 46.8% · 月活跃率 38.7%。",
