  "Progressive application": "渐进式申请",
  "“Apply in minutes — Step 1 of 3.” Mobile Number [Enter mobile number] [Continue]. 🛡 We'll verify your identity securely.": "“几分钟完成申请 — 第 1 / 3 步。”手机号 [输入手机号] [继续]。🛡 我们会安全地验证你的身份。",
  "Lower entry barrier and reduce drop-off.": "降低进入门槛并减少流失。",
  "Breaking the form into steps feels faster and easier for Gen Z users, especially on mobile.": "把表单拆成步骤，对 Z 世代用户（尤其在手机上）感觉更快、更容易。",
  "Higher completion rate": "更高的完成率",
