  "“Choose your top categories — Get more rewards in the categories you love.” Coffee 5% · Transit 5% · Food Delivery 5% · Online Shopping 5%. You can update anytime in settings.": "“选择你的主要类别 — 在你喜爱的类别获得更多奖励。”咖啡 5% · 交通 5% · 外卖 5% · 线上购物 5%。可随时在设置中更新。",
  "Merchant-based rewards": "基于商户的奖励",
  "“Your favorite brands — Earn more rewards at the places you love.” Seesaw 5% · M Stand 5% · % Arabica 5% · CHA BAI DAO 5%. You can update anytime in settings.": "“你最爱的品牌 — 在你喜爱的地方赚更多奖励。”Seesaw 5% · M Stand 5% · % Arabica 5% · CHA BAI DAO 5%。可随时在设置中更新。",
  "More flexible and future-proof.": "更灵活、更面向未来。",
