  "GRID SYSTEM": "网格系统",
  "12-column grid system. Flexible layout for digital and print. Slash module defines visual rhythm and directional momentum.": "12 列网格系统。为数字与印刷的灵活布局。斜杠模块定义视觉节奏与方向势头。",
