  "MATTE BLACK · CARBON WEAVE · MICRO LINE — Premium materials. Subtle details. Textures reflect technology, movement and individuality.": "哑光黑 · 碳编织 · 微线条 — 高端材质。微妙细节。纹理反映科技、运动与个性。",
  "GRADIENT RULES": "渐变规则",
  "— DIRECTION: gradients follow the slash angle to create a sense of forward momentum · CONTRAST: use on dark backgrounds to enhance energy and focus · BALANCE: combine with neutral tones to maintain clarity and premium feel.": "— 方向：渐变遵循斜杠角度，营造向前势头 · 对比：在深色背景上使用以增强能量与焦点 · 平衡：与中性色调结合，保持清晰与高端感。",
