  "PRIMARY DARK BACKGROUND · PRIMARY LIGHT BACKGROUND · ICON APP & FAVICON · WORDMARK CAMPAIGN USAGE. Clear space is defined by the height of the slash. Do not alter the angle, proportion or spacing.": "主深色背景 · 主浅色背景 · 图标应用与网站图标 · 字标活动用法。留白由斜杠高度定义。不得改变角度、比例或间距。",
  "PHOTOGRAPHY DIRECTION": "摄影方向",
  "Real, urban, forward-looking. Capture ambition, independence and the energy of a new generation. Use strong composition and the slash as a visual leading line.": "真实、都市、前瞻。捕捉雄心、独立与新一代的能量。使用强有力的构图，并以斜杠作为视觉引导线。",
  "MOTION PRINCIPLES — Fast. Smooth. Purposeful. Motion expresses progress and confidence. Duration: 200–500ms. Ease: Out.": "动效原则 — 快速。流畅。有目的。动效表达进步与自信。时长：200–500ms。缓动：Out。",
