  "Main phone as printed: Initial credit limit ¥8,000.00 › — Review your limit anytime in the app. Virtual Next Card [Active]: Next Card •••• •••• •••• 1234 · Valid Thru 12/28 · CVV 345 · 👁 [Add to wallet] [View card details]. Security setup — Protect your account in a few steps ›. First spend mission — Make your first transaction to activate more features. [Start mission]": "主手机如原文：初始信用额度 ¥8,000.00 › — 随时在应用内查看额度。Next Card 虚拟卡 [已激活]：Next Card •••• •••• •••• 1234 · 有效期至 12/28 · CVV 345 · 👁 [添加到钱包] [查看卡片详情]。安全设置 — 几步保护你的账户 ›。首刷任务 — 完成首笔交易以激活更多功能。[开始任务]",
  "We're reviewing your information. This usually takes 1–2 business days. What happens next: We'll notify you when there's an update · You can check your status anytime in the app. [View application details]. While you wait: Explore Next Card and learn how to manage your account ›.": "我们正在审核你的信息。通常需要 1–2 个工作日。接下来会怎样：有更新时我们会通知你 · 你可以随时在应用内查看状态。[查看申请详情]。等待期间：探索 Next Card 并了解如何管理你的账户 ›。",
  "We couldn't approve your application based on our current criteria. Possible reasons: Information didn't match our records · Credit profile didn't meet our criteria · Recent credit applications may affect approval. [View application details]. What you can do: You can reapply after 30 days. Learn how to improve your profile ›.": "按我们目前的标准，暂时无法批准你的申请。可能的原因：信息与我们的记录不符 · 信用档案未达标准 · 近期的信贷申请可能影响审批。[查看申请详情]。接下来你可以：30 天后重新申请。了解如何改善你的信用档案 ›。",
  "We're reviewing your application and may contact you for more information. What you can do: Keep your phone nearby in case we contact you · Check your email for any requests. [View application details]. While you wait: Explore Next Card and get ready for what's next ›.": "我们正在审核你的申请，可能联系你补充信息。接下来你可以：把手机带在身边，以便我们联系 · 留意邮箱中的请求。[查看申请详情]。等待期间：探索 Next Card，为下一步做好准备 ›。",
