  "Rewards screen:": "奖励页面：",
  "A transparent and engaging rewards experience built for China Gen Z. Design points as printed: Clear Points Balance — real-time balance with upcoming expiry · Category Rewards — earn more in what you love · Progress Tracking — see how close you are to your next reward · Earning Rules — simple and transparent · Flexible Redemption — multiple ways to use your points · Reward History — track every earning and redemption · Empty & Unavailable States — helpful guidance in every situation.": "为中国 Z 世代打造的透明且有吸引力的奖励体验。设计要点如原文：清晰的积分余额 — 实时余额与即将到期提醒 · 类别奖励 — 在你所爱上赚更多 · 进度追踪 — 看你离下一个奖励还有多近 · 赚取规则 — 简单透明 · 灵活兑换 — 多种使用积分的方式 · 奖励历史 — 追踪每一次赚取与兑换 · 空与不可用状态 — 每种情况下都有贴心引导。",
  "Points Balance 6,350 ≈ ¥63.50. Expiring on Dec 31, 2025: 1,200 pts. Your Progress — Silver | Spend ¥4,000 more to reach Gold · ¥6,000 / ¥10,000 (bar). Earn More [All Categories ›]: Dining — Earn 5 pts / ¥10 — 5X · Beverages — Earn 3 pts / ¥10 — 3X · Shopping — Earn 2 pts / ¥10 — 2X · Transportation — Earn 1 pt / ¥10 — 1X · Others — Earn 1 pt / ¥10 — 1X. Bottom nav: Home · Card · Rewards · Profile.": "积分余额 6,350 ≈ ¥63.50。2025 年 12 月 31 日到期：1,200 积分。你的进度 — 白银 | 再消费 ¥4,000 升至黄金 · ¥6,000 / ¥10,000（进度条）。赚更多 [全部类别 ›]：餐饮 — 每 ¥10 赚 5 积分 — 5 倍 · 饮品 — 每 ¥10 赚 3 积分 — 3 倍 · 购物 — 每 ¥10 赚 2 积分 — 2 倍 · 交通 — 每 ¥10 赚 1 积分 — 1 倍 · 其他 — 每 ¥10 赚 1 积分 — 1 倍。底部导航：首页 · 卡 · 奖励 · 我的。",
  "“Choose what you love, earn more.” Dining 5X (Earn 5 pts / ¥10) · Beverages 3X · Shopping 2X · Transportation 1X · Entertainment 1X · Others 1X.": "“选择你所爱，赚更多。”餐饮 5 倍（每 ¥10 赚 5 积分）· 饮品 3 倍 · 购物 2 倍 · 交通 1 倍 · 娱乐 1 倍 · 其他 1 倍。",
  "Tabs: Earn Points | Bonus Rules. Base Earning — 1 pt for every ¥10 spent (1X). Category Earning (Monthly) — earn more in your favorite categories: Dining 5 pts for every ¥10 spent (5X) · Beverages 3 pts (3X) · Shopping 2 pts (2X) · Transportation 1 pt (1X) · Others 1 pt (1X). Category updates on the 1st of each month. Points will be credited after the transaction settles.": "标签页：赚取积分 | 奖励规则。基础赚取 — 每消费 ¥10 赚 1 积分（1 倍）。类别赚取（月度）— 在你最爱的类别赚更多：餐饮每消费 ¥10 赚 5 积分（5 倍）· 饮品 3 积分（3 倍）· 购物 2 积分（2 倍）· 交通 1 积分（1 倍）· 其他 1 积分（1 倍）。类别每月 1 日更新。积分将在交易结算后入账。",
  "Dining Bonus — Earn 10X Points on Weekend Dining (10X). Validity: May 1 – Jun 30, 2025. Eligible Transactions: In-store & Online dining spend. How to Earn: Earn 10 pts for every ¥10 spent on dining during weekends. Offer Conditions: • Register before Jun 30, 2025 • Each account can earn up to 5,000 pts during the campaign. [Register Now] · Terms & Conditions.": "餐饮奖励 — 周末餐饮赚 10 倍积分（10 倍）。有效期：2025 年 5 月 1 日 – 6 月 30 日。符合资格的交易：门店与线上餐饮消费。如何赚取：周末餐饮每消费 ¥10 赚 10 积分。优惠条件：• 在 2025 年 6 月 30 日前注册 • 每个账户在活动期间最多可赚 5,000 积分。[立即注册] · 条款与条件。",
  "Available Points 6,350 ≈ ¥63.50. Tabs: All | Lifestyle | Digital | Merchandise. Lifestyle Vouchers — From 2,000 pts › · Partner Offers — From 1,500 pts › · Digital Subscriptions — From 1,000 pts › · Merchandise — From 3,000 pts › · Experiences — From 2,500 pts ›. Redemption rules ›.": "可用积分 6,350 ≈ ¥63.50。标签页：全部 | 生活方式 | 数字 | 商品。生活方式券 — 2,000 积分起 › · 伙伴优惠 — 1,500 积分起 › · 数字订阅 — 1,000 积分起 › · 商品 — 3,000 积分起 › · 体验 — 2,500 积分起 ›。兑换规则 ›。",
  "Tabs: All | Earned | Redeemed. May 2025 — Earned · Dining Spend · May 18, 2025 · 250 pts · Redeemed · Lifestyle Voucher · May 17, 2025 · −2,000 pts. May 2025 — Earned · Shopping Spend · May 12, 2025 · 480 pts · Earned · Bonus Points · May 10, 2025 · 300 pts. “That's all for now.” (Month header repeats in the original, as printed.)": "标签页：全部 | 已赚取 | 已兑换。2025 年 5 月 — 已赚取 · 餐饮消费 · 2025 年 5 月 18 日 · 250 积分 · 已兑换 · 生活方式券 · 2025 年 5 月 17 日 · −2,000 积分。2025 年 5 月 — 已赚取 · 购物消费 · 2025 年 5 月 12 日 · 480 积分 · 已赚取 · 奖励积分 · 2025 年 5 月 10 日 · 300 积分。“目前就这些。”（月份标题在原文中重复，如原文。）",
  "Lifestyle Voucher — ¥20 Café Voucher (café photograph as printed). 2,000 pts. Order Number R25051800123 · Redeemed On May 18, 2025 14:30 · Status Completed. [View Voucher]": "生活方式券 — ¥20 咖啡券（咖啡馆照片如原文）。2,000 积分。订单号 R25051800123 · 兑换时间 2025 年 5 月 18 日 14:30 · 状态 已完成。[查看券]",
  "“You don't have any rewards yet. Start earning points and come back!” [Explore Ways to Earn]": "“你还没有任何奖励。开始赚积分后再回来！”[探索赚积分方式]",
