  "“You need 2,000 pts to redeem this reward. Keep earning and try again!” [Explore Ways to Earn]": "“你需要 2,000 积分兑换此奖励。继续赚取，再来试试！”[探索赚积分方式]",
  "“This offer is no longer available. Explore other offers you might like.” [View Other Offers]": "“此优惠已不可用。探索你可能喜欢的其他优惠。”[查看其他优惠]",
