  "Curated offers around you. From late nights to daily commutes, enjoy more of your city. CITY TAB — Shenzhen or Guangzhou, tailored local picks · LIVE MAP & LIST — explore nearby perks in map or list view · MERCHANT DETAIL — offer conditions, distance, and merchant info · EASY REDEEM — show QR code in-store and enjoy the offer.": "你周围的精选优惠。从深夜到日常通勤，享受你的城市更多。城市标签 — 深圳或广州，定制本地精选 · 实时地图与列表 — 以地图或列表视图探索附近优惠 · 商户详情 — 优惠条件、距离与商户信息 · 轻松兑换 — 在门店出示二维码，享受优惠。",
  "Near you [See all] — All · Food & Drink · Café · Nightlife · Transit · Entertainment": "你附近 [查看全部] — 全部 · 美食与饮品 · 咖啡馆 · 夜生活 · 交通 · 娱乐",
  "The printed phones show the Shenzhen tab active; Guangzhou is the second city tab (its list is not shown on the slide). Map labels as printed around the active pins: COCO Park Shopping Mall · Futian CBD · Gangxia · Ping An Finance Center · Shenzhen Convention & Exhibition Center · Shenzhen Central Park.": "原图手机显示深圳标签激活；广州是第二个城市标签（其列表未在页面中展示）。激活图钉周围的地图标签如原文：COCO Park 购物中心 · 福田 CBD · 岗厦 · 平安金融中心 · 深圳会展中心 · 深圳中心公园。",
  "Printed map: dark street map of Futian with orange category pins and a blue “you are here” dot. Labels: COCO Park Shopping Mall · Futian CBD · Gangxia · Ping An Finance Center · Shenzhen Convention & Exhibition Center · Shenzhen Central Park. Tap a perk to open its detail:": "原图地图：福田的深色街道地图，带橙色类别图钉与蓝色“你在这里”圆点。标签：COCO Park 购物中心 · 福田 CBD · 岗厦 · 平安金融中心 · 深圳会展中心 · 深圳中心公园。点击一个优惠打开其详情：",
  "— detail page follows the same pattern as Morton's Bar on the printed slide (offer, QR redeem, about).": "— 详情页沿用原图 Morton's Bar 的同一版式（优惠、二维码兑换、商户介绍）。",
