  "Printed label: “EXPERIENCE 48” (this file's printed number runs one behind its file name). Invite friends to build your squad. Track progress, enjoy shared rewards, and stay in control with clear limitations and privacy settings. Left rail as printed: Build Your Squad — create your squad and invite friends with an invite link · Track Progress — see squad growth and referral status in real time · Shared Rewards — everyone earns when the squad achieves milestones · Fair and Safe — clear rules to prevent abuse and ensure a positive experience · Privacy First — you control what's shared and who can see your activity.": "原图标签：“EXPERIENCE 48”（此文件的印刷编号比文件名小一号）。邀请朋友组建你的小队。追踪进度、享受共享奖励，并以清晰的限制与隐私设置保持掌控。左栏如原文：组建你的小队 — 创建小队并用邀请链接邀请朋友 · 追踪进度 — 实时查看小队成长与推荐状态 · 共享奖励 — 小队达成里程碑时人人有奖 · 公平与安全 — 清晰规则防止滥用并确保积极体验 · 隐私优先 — 你掌控分享什么以及谁能看到你的动态。",
  "JOURNEY OVERVIEW": "旅程概览",
  "Set up your squad and get your unique invite link.": "设置你的小队并获得你的专属邀请链接。",
  "Create Your Squad — Invite friends to join Next Card. Grow your squad and unlock shared rewards together. [Create Squad] By continuing, you agree to the Squad Rules.": "创建你的小队 — 邀请朋友加入 Next Card。壮大你的小队，一起解锁共享奖励。[创建小队] 继续即表示你同意小队规则。",
  "Share the link through your preferred channel.": "通过你偏好的渠道分享链接。",
  "Your Invite Link — Share your link with friends. They get benefits. You both earn when they join and activate. [nextcard.cn/join/AB12CD] [Copy] · Share via: WeChat · Moments · SMS · More. Invite Tips: • Share with friends who may like Next Card. • Rewards are better with real connections. • You can track your squad anytime.": "你的邀请链接 — 与朋友分享你的链接。他们得权益。当他们加入并激活时，双方都得奖励。[nextcard.cn/join/AB12CD] [复制] · 分享方式：微信 · 朋友圈 · 短信 · 更多。邀请提示：• 与可能喜欢 Next Card 的朋友分享。• 真实连接的奖励更好。• 你可以随时追踪你的小队。",
  "Monitor invites and see who has joined.": "监控邀请并查看谁已加入。",
  "My Squad — Squad Progress 3/10 (arc) · 3 Joined · 7 Remaining · Next Milestone: 5 Joined. Tabs: All (3) | Joined (3) | Activated (2). Alex — Joined — May 12, 10:30 · Chris — Activated — May 13, 09:15 · Jamie — Joined — May 14, 14:20. [Invite More Friends]": "我的小队 — 小队进度 3/10（圆弧）· 3 人已加入 · 剩 7 人 · 下一里程碑：5 人加入。标签页：全部（3）| 已加入（3）| 已激活（2）。Alex — 已加入 — 5 月 12 日 10:30 · Chris — 已激活 — 5 月 13 日 09:15 · Jamie — 已加入 — 5 月 14 日 14:20。[邀请更多朋友]",
  "Unlock shared rewards when milestones are met.": "达成里程碑时解锁共享奖励。",
  "Milestone Reached — 5 Joined (gift visual as printed). Shared Reward — Everyone Gets ¥30. Reward Balance — Reward will be credited within 24 hours. Upcoming Milestone: 10 Joined — ¥80 (progress bar).": "里程碑达成 — 5 人加入（礼物视觉如原文）。共享奖励 — 人人得 ¥30。奖励余额 — 奖励将在 24 小时内入账。下一里程碑：10 人加入 — ¥80（进度条）。",
  "Manage privacy settings and stay protected.": "管理隐私设置并保持受保护。",
  "Privacy Controls (toggles on the printed phone): Show my squad activity — Allow friends to see your squad progress [ON] · Show my name — Allow friends to see your name in the squad [ON] · Allow direct messages — Allow friends to message you about Next Card [OFF]. Safety & Limitations: One reward per user — Rewards are limited to one account per user · No self-referrals — Invites must come from real connections · Suspicious activity — We may review or remove ineligible activity. Learn more about our Squad Rules.": "隐私控制（原图手机上的开关）：展示我的小队动态 — 允许朋友查看你的小队进度 [开] · 展示我的名字 — 允许朋友在小队中看到你的名字 [开] · 允许私信 — 允许朋友就 Next Card 私信你 [关]。安全与限制：每位用户一份奖励 — 奖励限每用户一个账户 · 禁止自我推荐 — 邀请必须来自真实连接 · 可疑活动 — 我们可能审核或移除不合格活动。了解我们的小队规则更多信息。",
  "Simulate a friend joining": "模拟一位朋友加入",
  "All milestones reached — top reward ¥80.": "全部里程碑已达成 — 最高奖励 ¥80。",
