  "Simple language": "简单语言",
  "Tip: Missions are designed to encourage responsible habits. Never spend just to complete a mission.": "提示：任务旨在鼓励负责任的习惯。切勿只为完成任务而消费。",
  "China Gen Z Credit Card Concept — complete missions that build smart money habits. Earn rewards for everyday actions that keep you in control. Build better habits — practical actions for everyday financial wellness · Earn meaningful rewards — useful credits and benefits, not more borrowing · Stay in control — clear progress, helpful tips, and full transparency.": "中国 Z 世代信用卡概念 — 完成任务，养成聪明的金钱习惯。因让你保持掌控的日常行动赚取奖励。养成更好的习惯 — 面向日常财务健康的实际行动 · 赚取有意义的奖励 — 有用的抵扣金与权益，而非更多借贷 · 保持掌控 — 清晰进度、贴心提示与完全透明。",
  "DESIGN PRINCIPLES: ☑ Encourage responsible actions · ☑ Transparent progress and rules · ☑ Accessible and easy to use · ☑ Rewards that add real value": "设计原则：☑ 鼓励负责任的行动 · ☑ 透明的进度与规则 · ☑ 无障碍且易于使用 · ☑ 带来真实价值的奖励",
  "Make 1 eligible purchase with your Next Card.": "用你的 Next Card 完成 1 笔符合资格的购买。",
  "¥18 Account Credit — ✓ Claimed": "¥18 账户抵扣金 — ✓ 已领取",
  "• Minimum transaction: ¥18 • Excludes cash advances and fees • Posted transactions only • May take up to 24 hours to update": "• 最低交易额：¥18 • 不含取现与费用 • 仅限已入账交易 • 更新可能需要最多 24 小时",
  "Set up repayment for your Next Card (mission row as printed on the list phone).": "为你的 Next Card 设置还款（任务行如列表手机原文）。",
  "Spend in any 3 different everyday categories.": "在任意 3 个不同的日常类别消费。",
  "• Categories: Transport, Food & Drink, Shopping, Lifestyle, Entertainment • Must be 3 different categories • Posted transactions only": "• 类别：交通、餐饮、购物、生活方式、娱乐 • 必须是 3 个不同类别 • 仅限已入账交易",
  "Make 1 purchase at a local merchant near you.": "在你附近的一家本地商户完成 1 笔购买。",
  "• Local merchant defined by transaction location • Minimum transaction: ¥12 • Excludes cash advances and fees • Posted transactions only": "• 本地商户按交易地点定义 • 最低交易额：¥12 • 不含取现与费用 • 仅限已入账交易",
  "Complete 1 financial-learning module in the Next Card Learning Center.": "在 Next Card 学习中心完成 1 个金融学习模块。",
  "• Modules take ~5–10 minutes • Must complete all lessons • Progress may take up to 24 hours to update": "• 模块约需 5–10 分钟 • 必须完成全部课程 • 进度更新可能需要最多 24 小时",
  "Missions refresh monthly. Some actions may take up to 24 hours to update. Bottom nav: Home · Activity · Pay · Missions (active) · Me.": "任务每月刷新。部分行动的更新可能需要最多 24 小时。底部导航：首页 · 动态 · 支付 · 任务（激活）· 我的。",
  "Your categories": "你的类别",
  "— tap to log a category spend:": "— 点击记录一笔类别消费：",
  "Show suggestions ⌄ (as printed).": "显示建议 ⌄（如原文）。",
  "Monthly Missions help you build smart financial habits with small, meaningful actions. Complete all missions to earn bonus rewards. Who can join — all Next Card cardholders in good standing · How it works — complete missions within the month; track progress in real time · Rewards — earn account credits and exclusive benefits · When rewards arrive — rewards are credited within 3 business days · Need help? — visit Help Center in the Next Card app.": "每月任务以小而有意义的行动帮你养成聪明的财务习惯。完成全部任务可赚奖励金。谁可以参加 — 所有状态良好的 Next Card 持卡人 · 如何运作 — 在当月完成任务；实时追踪进度 · 奖励 — 赚取账户抵扣金与专属权益 · 奖励何时到达 — 奖励在 3 个工作日内入账 · 需要帮助？— 访问 Next Card 应用内的帮助中心。",
  "🔊 Screen reader friendly": "🔊 屏幕阅读器友好",
  "◐ High contrast mode support": "◐ 支持高对比度模式",
  "Scalable text up to 200%": "文本可缩放至 200%",
  "▣ Clear focus indicators": "▣ 清晰的焦点指示",
  "☀ Color not the only way to understand": "☀ 颜色不是理解的唯一方式",
  "Simple language and icons": "简单语言与图标",
  "Responsibility tip: Spend within your means and pay on time. Good habits today, more freedom tomorrow.": "责任提示：量入为出，按时还款。今天的好习惯，明天的更多自由。",
