  "China Gen Z Credit Card Concept — a comprehensive QA matrix of Next Card across breakpoints, states, and accessibility scenarios to ensure a consistent, reliable experience for every user.": "中国 Z 世代信用卡概念 — Next Card 跨断点、状态与无障碍场景的综合 QA 矩阵，确保每位用户都有一致、可靠的体验。",
