  "STATE CATEGORIES — Loading · Empty · Error · Pending approval · Reward unavailable · Offline or slow network · Accessibility-focused": "状态类别 — 加载中 · 空 · 错误 · 待审批 · 奖励不可用 · 离线或慢网络 · 无障碍焦点",
  "GLOBAL BEHAVIORS — ✓ Consistent navigation and hierarchy · ✓ Clear feedback for every state · ✓ Accessible, inclusive, and usable · ✓ Resilient to network and device changes": "全局行为 — ✓ 一致的导航与层级 · ✓ 每个状态都有清晰反馈 · ✓ 无障碍、包容、可用 · ✓ 对网络与设备变化有韧性",
  "Skeleton layout adapts to content structure. Smooth, minimal motion.": "骨架布局适配内容结构。流畅、最小动效。",
  "Progressive skeletons prioritize key information. Maintains layout stability.": "渐进式骨架优先关键信息。保持布局稳定。",
  "Friendly empty state with clear guidance. Encourages next action.": "友好的空状态，带清晰引导。鼓励下一步行动。",
  "“No transactions yet — Start spending to see your activity here.”": "“暂无交易 — 开始消费，在这里查看你的动态。”",
  "Illustration and CTA guide users to get started. Action-oriented and optimistic.": "插图与 CTA 引导用户开始。行动导向且乐观。",
  "[Explore rewards]": "[探索奖励]",
  "Spacious layout clarifies the next best step. Reduces cognitive load.": "宽敞的布局让下一步更清晰。降低认知负荷。",
  "Clear error message with primary recovery option. Keeps users in control.": "清晰的错误信息，带主要恢复选项。让用户保持掌控。",
  "“Something went wrong — Please try again.” [Retry]": "“出了点问题 — 请重试。”[重试]",
  "Context-aware error with safe recovery. Maintains trust.": "情境感知的错误，恢复安全。维护信任。",
  "Error context explained with actionable step. Easy to recover.": "错误情境有解释，步骤可执行。容易恢复。",
  "Reassures user with timeline expectation. Sets clear expectations.": "以时间线预期让用户安心。设定清晰预期。",
  "“Application under review — We'll notify you soon.” [View status]": "“申请审核中 — 我们会尽快通知你。”[查看状态]",
  "Status visibility with option to check progress. Transparent and reliable.": "状态可见，可查看进度。透明可靠。",
  "Persistent status with easy access to details. Builds confidence.": "持久的状态，详情易达。建立信心。",
  "Explains limitation and suggests alternatives. Keeps engagement high.": "解释限制并建议替代。保持高互动。",
  "“Reward unavailable — This reward is not available at the moment.” [Browse other rewards]": "“奖励不可用 — 此奖励目前不可用。”[浏览其他奖励]",
  "Alternative path keeps the journey moving forward. Positive framing.": "替代路径让旅程继续前进。正向表述。",
  "Consistent tone and helpful alternative. Reduces friction.": "一致的语气与有用的替代。减少摩擦。",
  "Detects offline status and offers quick retry. Works in poor connectivity.": "检测离线状态并提供快速重试。在弱连接下可用。",
  "“You're offline — Check your connection and try again.” [Retry]": "“你已离线 — 检查你的连接并重试。”[重试]",
  "Supports network recovery with minimal steps. Resilient by design.": "以最少步骤支持网络恢复。韧性内置于设计。",
  "Guides user to restore connection and continue. Leaves no one behind.": "引导用户恢复连接并继续。不落下任何人。",
