  "Approved? A virtual card is live instantly and can be bound to Alipay / WeChat Pay immediately.": "审批通过？虚拟卡即时生效，可立即绑定支付宝 / 微信支付。",
  "Physical Card Shipping & Customization": "实体卡寄送与定制",
