  // ---- content/real/nextCard.ts ----
  "Gen Z Credit Card Growth System for China": "面向中国的 Z 世代信用卡增长系统",
  "Next Card is a 60-second-onboarding credit card and growth system designed for Gen Z in China — low initial limits, SQUAD referrals, monthly missions and benefit exploration instead of a points-only card.": "Next Card 是一套为中国 Z 世代设计的信用卡与增长系统：60 秒开卡 — 低初始额度、小队推荐、每月任务与权益探索，而非一张纯积分卡。",
  "CREDIT CARD · GROWTH SYSTEM · CONCEPT": "信用卡 · 增长系统 · 概念",
  "Competition Concept": "竞赛概念",
  "Role": "角色",
  "Lead Product Designer": "首席产品设计师",
  "Team": "团队",
  "1 Designer, 2 Strategy Consultants": "1 名设计师、2 名战略顾问",
  "Timeline": "时间",
  "Scope": "范围",
  "Research > Strategy > UX > UI > Prototype": "研究 > 战略 > UX > UI > 原型",
  "Constraints": "约束",
  "Low limits, no cash-out rewards, China compliance": "低额度、无套现奖励、中国合规",
  "What I owned end to end: the growth thesis, city and channel strategy, the 60-second risk-aware onboarding flow, the reward engine math, and the full 60+ screen high-fidelity prototype — 8 weeks from blank page to competition final.": "我端到端负责：增长论点、城市与渠道战略、60 秒且内嵌风控的开卡流程、奖励引擎的测算，以及完整的 60+ 屏高保真原型 — 8 周，从白纸到竞赛决赛。",
  "Target population": "目标人群",
  "6-month target": "6 个月目标",
  "Target CAC": "目标 CAC",
  "Activation rate": "激活率",
  "Will Gen Z apply if the answer is fast enough?": "如果答案够快，Z 世代会申请吗？",
  "Incumbent onboarding took 7–15 days branch-based; challenger banks had trained users to expect an answer in minutes.": "传统银行的开卡要 7–15 天、还得跑网点；挑战者银行早已把用户的期待训练成分钟级答复。",
  "Keep the long branch flow / Copy a neobank flow 1:1": "保留漫长的网点流程 / 1:1 复制新银行流程",
  "60-second OCR + liveness + tiered-limit approval": "60 秒 OCR + 活体 + 分层额度审批",
  "Speed is the acquisition channel for this generation; risk is managed by limit tiers, not by slowing everyone down.": "速度是这一代人的获客渠道；风险由额度分层管理，而非让所有人变慢。",
  "The full deck is built around the 60-second promise; every screen either protects it or pays for it.": "整个方案围绕 60 秒承诺构建；每一屏要么保护它，要么为它买单。",
  "How do you grow a card without cash-bait?": "如何在不用现金诱饵的情况下增长一张卡？",
  "Cashback-led growth in China was being regulated and burned margin; surveys showed 68% of Gen Z trusted friends over ads.": "中国以返现主导的增长正被监管且烧利润；调查显示 68% 的 Z 世代信任朋友胜过广告。",
  "Referral cash bonuses / Paid KOL-only launch": "推荐现金奖励 / 纯付费 KOL 上线",
  "SQUAD mechanics + monthly missions + city IP campaigns": "小队机制 + 每月任务 + 城市 IP 活动",
  "Social proof is the cheapest CAC; missions convert one activation into a habit loop the points card never built.": "社交证明是最便宜的 CAC；任务把一次激活转化为积分卡从未建立的习惯闭环。",
  "Reward engine math is checked against a 0.8% exchange guardrail before any campaign ships.": "奖励引擎数学在任何活动上线前都按 0.8% 兑换护栏校验。",
  "What makes a first card feel safe to hold?": "什么让第一张卡拿着有安全感？",
  "First-card anxiety centred on hidden fees and debt spirals; Chinese regulators had just tightened student-card rules.": "第一张卡的焦虑集中在隐藏费用与债务螺旋；中国监管刚收紧学生卡规则。",
  "Higher limits to compete / Gamified credit-score chasing": "以更高额度竞争 / 游戏化追逐信用分",
  "¥3,000 starter limit, credit-builder coaching, no cash-out redemptions": "¥3,000 起始额度、信用建设辅导、无套现兑换",
  "Trust is the retention feature: a card parents tolerate and regulators allow outlives a generous card that gets pulled.": "信任是留存功能：一张父母容忍、监管允许的卡，比一张被下架的慷慨卡活得久。",
  "Limit-growth screens now show the rule ('keep utilization under 30%') instead of a black-box score.": "额度成长页面现在展示规则（“保持使用率低于 30%”）而非黑箱分数。",
  "Growth thesis + evidence base": "增长论点 + 证据基础",
  "Deck / market model": "方案 / 市场模型",
  "Judgment call: anchor on the 102M Gen-Z cohort, not on incumbent card penetration.": "判断：锚定 1.02 亿 Z 世代人群，而非传统卡渗透率。",
  "City + channel strategy": "城市 + 渠道战略",
  "Launch-city scorecard": "上线城市评分卡",
  "Figma + spreadsheet": "Figma + 电子表格",
  "Judgment call: Shenzhen/Guangzhou density over a national spray.": "判断：深圳/广州密度胜过全国撒网。",
  "Onboarding + risk UX": "开卡 + 风险 UX",
  "60-screen Hi-fi prototype": "60 屏高保真原型",
  "Judgment call: tier the limit, never gate the answer.": "判断：额度分层，答案永不设卡。",
  "Reward engine": "奖励引擎",
