  "Claude": "Claude",
  "Judgment call: cap category bonuses so the 0.8% guardrail holds at p90 behaviour.": "判断：封顶类别奖励，使 0.8% 护栏在 p90 行为下仍成立。",
  "Missions + SQUAD system": "任务 + 小队系统",
  "Loop diagrams / spec": "闭环图 / 规格",
  "Judgment call: reward the behaviour (transit rides), not the spend amount.": "判断：奖励行为（公交出行），而非消费金额。",
  "Campaign + measurement": "活动 + 度量",
  "90-day launch calendar": "90 天上线日历",
  "Judgment call: pre-commit kill/scale thresholds before launch emotion sets in.": "判断：在上线情绪形成前预先承诺终止/扩张阈值。",
  "Start from the answer": "从答案开始",
  "The opening screen promises a decision in 15 seconds — before a single feature is mentioned.": "开场屏在提到任何功能之前，先承诺 15 秒内给出决定。",
  "The exact moment the segment's #1 anxiety — 'will I be rejected publicly?' — is retired.": "该人群第一焦虑 — “我会不会被当众拒绝？”— 被消除的确切时刻。",
  "Research you can audit": "可审计的研究",
  "8 streams, 18 interviews, 214 survey responses and a competitor teardown, all sourced on-slide.": "8 个流、18 次访谈、214 份问卷回复与竞品拆解，全部在页面上标注来源。",
  "Trust is built in the footnotes before it is built in the funnel.": "信任先在脚注中建立，再在漏斗中建立。",
