  "TAM/SAM/SOM, activation equation and sensitivity bands instead of a single heroic forecast.": "TAM/SAM/SOM、激活方程与敏感度区间，而非单一的英雄式预测。",
  "Judges attack assumptions; ranges survive, point estimates don't.": "评委攻击假设；区间能存活，单点估计不能。",
  "Two launch cities, argued": "两个上线城市，有理有据",
  "Shenzhen and Guangzhou scored on density, transit behaviour and merchant mix — not on team preference.": "深圳与广州按密度、交通行为与商户组合评分 — 而非团队偏好。",
  "Density beats coverage for a referral-driven launch.": "对推荐驱动的上线，密度胜过覆盖。",
  "Acquisition is a system": "获客是一个系统",
  "Landing, onboarding, missions, SQUAD and city campaigns drawn as one loop with owners and metrics.": "落地页、开卡、任务、小队与城市活动画成一个闭环，每一环都有负责人与指标。",
  "Growth decks usually show channels; this one shows the machine.": "增长方案通常展示渠道；这个展示的是机器。",
  "The flow, all 60 screens": "流程，全部 60 屏",
  "Wireframe wall of the full journey — landing to activation to first mission.": "完整旅程的线框墙 — 从落地页到激活到第一个任务。",
  "Completeness is the credibility signal in a design competition.": "在设计竞赛中，完整性就是可信度信号。",
  "Eligibility without fear": "无恐惧的资格审查",
  "Risk checks are framed as 'what helps you get approved', with a credit-builder path for declines.": "风险检查被讲成「什么能帮你获批」，被拒的用户则有信用建设路径可走。",
  "A declined Gen-Z applicant is a future prime customer, not a dead end.": "被拒的 Z 世代申请人是未来的优质客户，而非死路。",
  "Reward engine, transparent": "奖励引擎，透明",
  "Category multipliers with a monthly bonus cap and a redemption floor, printed in the UI.": "类别倍数带月度奖励上限与兑换门槛，印在 UI 中。",
  "Users churn when points feel like a black box; the rules are the feature.": "当积分像黑箱时用户流失；规则本身就是功能。",
  "Missions, not just points": "任务，不只是积分",
  "First-transit-ride and first-bill missions teach the card's job in week one.": "首次公交出行与首次账单任务在第一周教会卡的用途。",
  "Habit formation beats balance accumulation for a first card.": "对第一张卡而言，习惯养成胜过余额积累。",
  "SQUAD referral mechanics": "小队推荐机制",
  "Invite 5 friends, everyone unlocks the same perk — no leaderboards, no cash.": "邀请 5 位朋友，所有人解锁同一权益 — 无排行榜、无现金。",
  "Equal-split rewards keep it social instead of mercenary.": "平分奖励让它保持社交而非雇佣兵式。",
  "City IP campaign kit": "城市 IP 活动包",
  "Transit-wrapped creative and merchant co-op for the two launch cities.": "为两个上线城市设计的交通包装创意与商户合作。",
  "Local fame first; national media later, if earned.": "先本地出名；全国媒体靠后，凭实力赢得。",
  "The dashboard after approval": "审批后的主页",
  "Limit, next bill and mission progress above the fold — no marketing modules.": "额度、下期账单与任务进度在首屏 — 无营销模块。",
  "A first card's home screen is a control panel, not a storefront.": "第一张卡的主页是控制面板，不是橱窗。",
  "Benefit exploration": "权益探索",
  "A map-first perk browser for the user's own neighbourhood.": "以地图优先的权益浏览器，面向用户自己的社区。",
  "Benefits people can walk to beat benefits they must remember.": "能步行到达的权益，胜过需要记住的权益。",
  "Credit builder path": "信用建设路径",
  "Small-limit ladder with explicit unlock rules and on-time streaks.": "小额度阶梯，带明确的解锁规则与按时还款连续记录。",
  "The decline path is designed, not abandoned.": "被拒路径也经过设计，而不是被放弃。",
