  // ---- Pass 9: exact whole-string additions (case intro, decisions, workflow, gallery, components, aria labels) ----
  "A strategic pivot for a leading Chinese commercial bank (>30% affluent market share) facing stalled affluent growth. The system re-targets Gen Z (born 1996-2010) with frictionless onboarding, digital-native perks, and viral acquisition, aiming for 300K new cards within a 6-month launch window across the Pearl River Delta.": "一家头部商业银行的战略转向：富裕客群市占率 >30%，增长却已停滞。这套体系重新瞄准 Z 世代（1996–2010 年出生），以无摩擦开卡、数字原生权益与裂变式获客，在珠三角 6 个月的首发窗口内拿下 300K 张新卡。",
  "A strategic credit card growth system targeting 28.3M Gen Z consumers in China's Pearl River Delta. Designed the complete product lifecycle from 60-second onboarding with OCR/biometric verification through virtual card instant-issuance, dynamic rewards, and responsible credit progression -- addressing the core challenge of acquiring young adults with no credit history in a market dominated by mobile payments.": "面向中国珠三角 28.3M 名 Z 世代消费者的信用卡增长体系。设计覆盖完整的产品生命周期：60 秒开卡（OCR 与生物识别核验）、虚拟卡即时发卡、动态奖励与负责任的信用成长——直面核心难题：在移动支付主导的市场里，获取没有信用记录的年轻用户。",
  "Should approval happen before or after card customization?": "审批应该在卡面定制之前，还是之后？",
  "Users described approval uncertainty as the highest-friction point in competitor onboarding flows.": "用户普遍反映，竞品开卡流程里摩擦最大的，就是审批结果不确定。",
  "A. Customize card first, then approve": "A. 先定制卡面，再审批",
  "B. Approve first, then customize": "B. 先审批，再定制卡面",
  "C. Parallelize both steps": "C. 两步并行",
  "Approve first.": "先审批。",
  "Avoid asking users to invest emotional effort into customizing a product they may not receive. Reduces perceived risk of rejection.": "不要让用户为一张可能拿不到的卡先投入情感成本。先审批，能降低被拒的心理风险。",
  "Moved all customization to post-approval activation flow. Reduced drop-off by removing speculative engagement.": "全部定制环节移到审批通过后的激活流程。去掉投机式的提前参与，流失随之减少。",
  "Should reward categories be manually selected or automatically applied?": "奖励类别应该由用户手动选择，还是自动生效？",
  "Research showed Gen Z users repeatedly missed reward qualification rules and forgot to activate categories.": "研究发现，Z 世代用户屡屡错过奖励资格规则，也常忘记激活类别。",
  "A. Manual category selection each month": "A. 每月手动选择类别",
  "B. Automatic highest-spend category": "B. 自动按消费最高类别计奖",
  "C. Fixed categories": "C. 固定类别",
  "Automatic highest-spend category.": "自动按消费最高类别计奖。",
  "Removes a recurring decision from the customer. Maximizes perceived reward without requiring ongoing attention.": "免去用户反复做决定；无需持续关注，也能拿到最高回报。",
  "How should credit limits grow for users with no credit history?": "没有信用记录的用户，额度该如何成长？",
  "Traditional credit scoring excludes most students and early-career workers. Alternative data (payment behavior) provides a viable signal.": "传统信用评分把大多数学生与职场新人挡在门外；替代数据（支付行为）能提供可用的信号。",
  "A. Fixed limit for 12 months": "A. 固定额度 12 个月",
  "B. Step-up reviews after on-time payments": "B. 按时还款后阶梯复审提额",
  "C. Income-based scaling": "C. 按收入规模定额",
  "Step-up reviews after 3 consecutive on-time payments.": "连续 3 次按时还款后，阶梯复审提额。",
  "Builds trust progressively while managing bank risk exposure. Creates a gamified sense of progression.": "在控制银行风险敞口的同时逐步建立信任，并以游戏化的进阶感推动用户前进。",
  "8-source evidence matrix": "8 个来源的证据矩阵",
  "Claude + manual source review": "Claude + 人工来源审阅",
  "Separated market evidence from inference; validated census data against merchant coverage reports": "把市场证据与推断分开；用商户覆盖报告交叉验证人口普查数据",
  "6 alternative onboarding flows": "6 套备选开卡流程",
  "Reduced to 3 based on compliance constraints and friction analysis": "依合规约束与摩擦分析收敛到 3 套",
  "System Design": "系统设计",
  "Component library + design tokens": "组件库 + 设计令牌",
  "Established reusable patterns for card states, transaction feeds, and reward displays": "沉淀可复用的卡片状态、交易流水与奖励展示模式",
  "Interactive React onboarding flow": "可交互的 React 开卡流程",
  "Tested against realistic KYC states including approval, manual review, and rejection paths": "按真实 KYC 状态测试，覆盖审批通过、人工审核与拒绝路径",
  "Edge-state audit": "边缘状态审计",
  "Manual review": "人工审核",
  "Identified 6 missing states including network timeout during biometric and partial-approval scenarios": "找出 6 个缺失状态，包括生物识别时网络超时与部分审批通过的情形",
  "Final presentation deck + interactive demo": "最终展示稿 + 可交互演示",
  "Aligned design narrative with business metrics for competition judges": "让设计叙事与业务指标对齐，供竞赛评委评判",
