  "Original Submission Overview": "原始提案总览",
  "The original submission overview — an India-market concept (Bengaluru / Mumbai / Delhi NCR, ₹ figures, cardholder name as printed) interleaved with the China proposal.": "原始提案总览 — 一个印度市场概念（班加罗尔 / 孟买 / 德里国家首都区、₹ 金额、持卡人姓名如原图）与中国提案交错呈现。",
  "The original submission kept in the record, as submitted.": "原始提案按提交原样保留在记录中。",
  "Launch-city reasoning: where Next Card should enter first, and why.": "首发城市论证：Next Card 应该先进入哪里、为什么。",
  "Geography as a product decision.": "地理本身就是一项产品决策。",
  "What to Build": "要构建什么",
