  "Brand": "品牌",
  "Why Shenzhen and Guangzhou win the launch-city comparison.": "为什么深圳与广州在首发城市比较中胜出。",
  "The city decision argued from the framework, not preference.": "城市决策来自框架论证，而非偏好。",
  "TAM, SAM and SOM funnel for the target market.": "目标市场的 TAM、SAM 与 SOM 漏斗。",
  "Market sizing as a funnel, with each layer earned.": "市场规模做成漏斗，每一层都有依据。",
  "The acquisition conversion equation as printed — its stage rates and counts are shown on the slide itself.": "如原图呈现的获客转化等式 — 各阶段比率与数量都在幻灯片本身上。",
  "The equation presented as printed, without smoothing its arithmetic.": "等式按原样呈现，不粉饰其算术。",
  "Scenario matrix (Conservative ~144K, Base approximately 300K, Upside ~462K approved cards) with a tornado analysis: application volume ±60K is the most influential driver, then approval rate ±30K, then activation rate ±25K. All results Modeled.": "情景矩阵（保守 ~144K、基准约 300K、乐观 ~462K 张获批卡）与龙卷风分析：申请量 ±60K 是影响最大的驱动因素，其次是审批通过率 ±30K、激活率 ±25K。全部结果为模型测算。",
  "Assessing the impact of conversion assumptions on approved cards — and naming which assumption matters most.": "评估转化假设对获批卡量的影响 — 并指出哪条假设最关键。",
  "Behavioral Segments": "行为分群",
  "Four behavioral segments, four journeys — one card that adapts.": "四个行为分群、四条旅程 — 一张能适配的卡。",
  "Segments defined by behaviour, not demographics.": "分群按行为定义，而非人口属性。",
  "Jobs, pains, and desired outcomes for the target users.": "目标用户的任务、痛点与期望结果。",
  "The JTBD view of the same users the segments describe.": "从 JTBD 视角看分群所描述的同一批用户。",
  "The full 11-stage end-to-end customer journey.": "完整的 11 阶段端到端客户旅程。",
  "The journey at full length, including the unglamorous stages.": "旅程按全长呈现，包括不光鲜的阶段。",
  "One Card. Six Value Engines": "一张卡，六大价值引擎",
  "One card, six value engines — the proposition broken into its six drivers.": "一张卡、六大价值引擎 — 把产品主张拆成六个驱动因素。",
  "The proposition as a system of engines, not a feature list.": "产品主张是一套引擎系统，而非功能清单。",
  "Frictionless Onboarding & Verification": "无摩擦开卡与核验",
  "The value triangle framing the Next Card proposition.": "框定 Next Card 主张的价值三角。",
  "Value has to balance for more than one party.": "价值必须对不止一方成立。",
  "Five principles guide every decision: useful every week not once a year; digital by default; local before national; social without encouraging irresponsible spending; credit growth through transparent behavior (progress ring 720 of 850).": "五项原则指引每个决策：每周有用，而非一年一次；数字优先；先本地、后全国；可以社交，但不鼓励不负责任的消费；以透明行为推动信用成长（进度环 720 / 850）。",
  "Designed for China's Gen Z. Built for real life — principles stated as weekly, local, guarded behavior, not slogans.": "为中国 Z 世代而设计，为真实生活而造 — 原则落到每周、本地与有护栏的行为上，而非口号。",
  "18+ filter, status selection, instant approval (¥8,000 limit), manual-review fallback.": "18 岁以上过滤、身份状态选择、即时审批（¥8,000 额度），以及人工审核兜底。",
  "Transparent decisioning reducing user anxiety.": "透明的审批决策，缓解用户焦虑。",
  "The product ecosystem map — app, card, perks, and partners as one system.": "产品生态地图 — App、卡片、权益与合作伙伴作为一个系统。",
  "The ecosystem drawn before its screens.": "先画生态，再画它的界面。",
  "Information architecture for the Next Card app.": "Next Card App 的信息架构。",
  "Structure before surface.": "先结构，后表层。",
  "The primary acquisition flow, step by step.": "主要获客流程，逐步呈现。",
  "The flow the growth model depends on.": "增长模型所依赖的那条流程。",
  "Retention Loop": "留存回路",
