  "Points Balance 6,350 ≈ ¥63.50. Expiring on Dec 31, 2025: 1,200 pts. Your Progress — Silver | Spend ¥4,000 more to reach Gold · ¥6,000 / ¥10,000 (bar). Earn More: Dining 5X · Beverages 3X · Shopping 2X · Transportation 1X · Others 1X. Bottom nav: Home · Card · Rewards · Profile.": "积分余额 6,350 ≈ ¥63.50。2025 年 12 月 31 日过期：1,200 积分。你的进度 — 白银 | 再消费 ¥4,000 升黄金 · ¥6,000 / ¥10,000（进度条）。赚更多：餐饮 5X · 饮品 3X · 购物 2X · 交通 1X · 其他 1X。底部导航：首页 · 卡片 · 奖励 · 我的。",
  "“Choose what you love, earn more.” Dining 5X · Beverages 3X · Shopping 2X · Transportation 1X · Entertainment 1X · Others 1X. Base earning is 1 pt / ¥10 for all eligible spend.": "「选你所爱，赚更多。」餐饮 5X · 饮品 3X · 购物 2X · 交通 1X · 娱乐 1X · 其他 1X。所有合格消费的基础赚取为每 ¥10 得 1 积分。",
  "Tabs: Earn Points | Bonus Rules. Base Earning — 1 pt for every ¥10 spent (1X). Category Earning (Monthly): Dining 5X · Beverages 3X · Shopping 2X · Transportation 1X · Others 1X. Category updates on the 1st of each month. Points will be credited after the transaction settles.": "标签页：赚积分 | 加赠规则。基础赚取 — 每消费 ¥10 得 1 积分（1X）。类别赚取（每月）：餐饮 5X · 饮品 3X · 购物 2X · 交通 1X · 其他 1X。类别每月 1 日更新。积分在交易入账后到账。",
  "Dining Bonus — Earn 10X Points on Weekend Dining. Validity: May 1 – Jun 30, 2025. Eligible: In-store & Online dining spend. Earn 10 pts for every ¥10 spent on dining during weekends. Conditions: Register before Jun 30, 2025 · Each account can earn up to 5,000 pts during the campaign.": "餐饮加赠 — 周末餐饮赚 10X 积分。有效期：2025 年 5 月 1 日 – 6 月 30 日。适用：到店与线上餐饮消费。周末餐饮每消费 ¥10 得 10 积分。条件：2025 年 6 月 30 日前报名 · 每个账户活动期间最多赚 5,000 积分。",
  "Available Points 6,350 ≈ ¥63.50. Tabs: All | Lifestyle | Digital | Merchandise. Lifestyle Vouchers — From 2,000 pts · Partner Offers — From 1,500 pts · Digital Subscriptions — From 1,000 pts · Merchandise — From 3,000 pts · Experiences — From 2,500 pts. Redemption rules ›.": "可用积分 6,350 ≈ ¥63.50。标签页：全部 | 生活方式 | 数字 | 实物。生活方式券 — 2,000 积分起 · 合作伙伴优惠 — 1,500 积分起 · 数字订阅 — 1,000 积分起 · 实物商品 — 3,000 积分起 · 体验 — 2,500 积分起。兑换规则 ›。",
  "Tabs: All | Earned | Redeemed. May 2025 — Earned · Dining Spend · May 18, 2025 · 250 pts · Redeemed · Lifestyle Voucher · May 17, 2025 · −2,000 pts · Earned · Shopping Spend · May 12, 2025 · 480 pts · Earned · Bonus Points · May 10, 2025 · 300 pts. “That's all for now.”": "标签页：全部 | 已赚取 | 已兑换。2025 年 5 月 — 已赚取 · 餐饮消费 · 2025 年 5 月 18 日 · 250 积分 · 已兑换 · 生活方式券 · 2025 年 5 月 17 日 · −2,000 积分 · 已赚取 · 购物消费 · 2025 年 5 月 12 日 · 480 积分 · 已赚取 · 加赠积分 · 2025 年 5 月 10 日 · 300 积分。「就到这里了。」",
  "Lifestyle Voucher — ¥20 Café Voucher. 2,000 pts. Order Number R25051800123 · Redeemed On May 18, 2025 14:30 · Status Completed. [View Voucher]": "生活方式券 — ¥20 咖啡券。2,000 积分。订单号 R25051800123 · 兑换时间 2025 年 5 月 18 日 14:30 · 状态 已完成。[查看券]",
  "Empty state — “You don't have any rewards yet. Start earning points and come back!” [Explore Ways to Earn]": "空状态 —「你还没有任何奖励。开始赚积分，再回来看看！」[探索赚取方式]",
  "Empty state — “There are no available offers now. Check back later for exciting rewards.” [View All Offers]": "空状态 —「目前没有可用优惠。稍后再来看看精彩奖励。」[查看全部优惠]",
  "Empty state — “You need 2,000 pts to redeem this reward. Keep earning and try again!” [Explore Ways to Earn]": "空状态 —「兑换这份奖励需要 2,000 积分。继续赚，再来试试！」[探索赚取方式]",
  "Empty state — “This offer is no longer available. Explore other offers you might like.” [View Other Offers]": "空状态 —「这份优惠已不可用。看看其他你可能喜欢的优惠。」[查看其他优惠]",
